require "test_helper"

# Vectors are copied from the published BIPs (32, 49, 84), not generated by this code.
class BitcoinExtendedKeyTest < ActiveSupport::TestCase
  # BIP84: account 0 of the "abandon … about" mnemonic, m/84'/0'/0'
  BIP84_ZPUB = "zpub6rFR7y4Q2AijBEqTUquhVz398htDFrtymD9xYYfG1m4wAcvPhXNfE3EfH1r1ADqtfSdVCToUG868RvUUkgDKf31mGDtKsAYz2oz2AGutZYs".freeze

  # BIP49: account 0 (testnet), m/49'/1'/0'
  BIP49_UPUB = "upub5EFU65HtV5TeiSHmZZm7FUffBGy8UKeqp7vw43jYbvZPpoVsgU93oac7Wk3u6moKegAEWtGNF8DehrnHtv21XXEMYRUocHqguyjknFHYfgY".freeze

  test "derives BIP84 receive and change addresses from a zpub" do
    key = BitcoinExtendedKey.parse(BIP84_ZPUB)

    assert_equal :mainnet, key.network
    assert_equal :p2wpkh, key.script
    assert_equal "bc1qcr8te4kr609gcawutmrza0j4xv80jy8z306fyu", key.address_at(0, 0)
    assert_equal "bc1qnjg0jd8228aq7egyzacy8cys3knf9xvrerkf9g", key.address_at(0, 1)
    assert_equal "bc1q8c6fshw2dlwun7ekn9qwf37cu2rn755upcp6el", key.address_at(1, 0)
  end

  test "derives the BIP84 child public key" do
    key = BitcoinExtendedKey.parse(BIP84_ZPUB).derive(0, 0)

    assert_equal "0330d54fd0dd420a6e5f8d3624f5f3482cae350f79d5f0753bf5beef9c2d91af3c", key.public_key.unpack1("H*")
  end

  test "derives the BIP49 nested SegWit address from a upub" do
    key = BitcoinExtendedKey.parse(BIP49_UPUB)

    assert_equal :testnet, key.network
    assert_equal :p2sh_p2wpkh, key.script
    assert_equal "03a1af804ac108a8a51782198c2d034b28bf90c8803f5a53f76276fa69a4eae77f", key.derive(0, 0).public_key.unpack1("H*")
    assert_equal "2Mww8dCYPUpKHofjgcXcBCEGmniw9CoaiD2", key.address_at(0, 0)
  end

  test "matches the BIP32 vector 1 public derivation chain" do
    parent = BitcoinExtendedKey.parse("xpub6D4BDPcP2GT577Vvch3R8wDkScZWzQzMMUm3PWbmWvVJrZwQY4VUNgqFJPMM3No2dFDFGTsxxpG5uJh7n7epu4trkrX7x7DogT5Uv6fcLW5")

    child = parent.child(2)
    assert_equal "xpub6FHa3pjLCk84BayeJxFW2SP4XRrFd1JYnxeLeU8EqN3vDfZmbqBqaGJAyiLjTAwm6ZLRQUMv1ZACTj37sR62cfN7fe5JnJ7dh8zL4fiyLHV", child.to_s

    grandchild = child.child(1_000_000_000)
    assert_equal "xpub6H1LXWLaKsWFhvm6RVpEL9P4KfRZSW7abD2ttkWP3SSQvnyA8FSVqNTEcYFgJS2UaFcxupHiYkro49S8yGasTvXEYBVPamhGW6cFJodrTHy", grandchild.to_s
  end

  test "matches the BIP32 vector 2 public derivation from the master key" do
    master = BitcoinExtendedKey.parse("xpub661MyMwAqRbcFW31YEwpkMuc5THy2PSt5bDMsktWQcFF8syAmRUapSCGu8ED9W6oDMSgv6Zz8idoc4a6mr8BDzTJY47LJhkJ8UB7WEGuduB")

    assert_equal "xpub69H7F5d8KSRgmmdJg2KhpAK8SR3DjMwAdkxj3ZuxV27CprR9LgpeyGmXUbC6wb7ERfvrnKZjXoUmmDznezpbZb7ap6r1D3tgFxHmwMkQTPH", master.child(0).to_s
  end

  test "an xpub derives legacy P2PKH addresses" do
    key = BitcoinExtendedKey.parse("xpub661MyMwAqRbcFW31YEwpkMuc5THy2PSt5bDMsktWQcFF8syAmRUapSCGu8ED9W6oDMSgv6Zz8idoc4a6mr8BDzTJY47LJhkJ8UB7WEGuduB")

    assert_equal :p2pkh, key.script
    assert_equal :p2pkh, BitcoinAddress.parse(key.address_at(0, 0)).type
  end

  test "refuses hardened derivation" do
    key = BitcoinExtendedKey.parse(BIP84_ZPUB)

    assert_raises(BitcoinExtendedKey::InvalidKey) { key.child(BitcoinExtendedKey::HARDENED) }
  end

  test "refuses an extended private key with a pointed message" do
    error = assert_raises(BitcoinExtendedKey::InvalidKey) do
      BitcoinExtendedKey.parse("zprvAdG4iTXWBoARxkkzNpNh8r6Qag3irQB8PzEMkAFeTRXxHpbF9z4QgEvBRmfvqWvGp42t42nvgGpNgYSJA9iefm1yYNZKEm7z6qUWCroSQnE")
    end

    assert_match(/private key/, error.message)
  end

  test "rejects a key with a bad checksum" do
    tampered = BIP84_ZPUB.sub(/s\z/, "t")

    assert_raises(BitcoinExtendedKey::InvalidKey) { BitcoinExtendedKey.parse(tampered) }
  end

  test "recognises extended key strings by shape" do
    assert BitcoinExtendedKey.extended_key?(BIP84_ZPUB)
    assert_not BitcoinExtendedKey.extended_key?("bc1qcr8te4kr609gcawutmrza0j4xv80jy8z306fyu")
  end
end
